from typing import Protocol, runtime_checkable

@runtime_checkable
class Closer(Protocol):
    def close(self) -> None: ...

class Socket:
    def close(self) -> None:
        print("закрыт")

class Fake:
    close = 5

print(isinstance(Socket(), Closer), isinstance(Fake(), Closer), isinstance("hi", Closer))

